     pub open spec fn _state_validation(self) -> bool {
         let new_spec = self.spec->0;
         &&& self.spec is Some
         &&& new_spec.replicas is Some ==> new_spec.replicas->0 >= 0
         // &&& new_spec.pod_management_policy is Some
         //     ==> (new_spec.pod_management_policy->0 == "OrderedReady"@
